SELECT 
FROM andon_record
WHERE is_deleted = 0

    AND (description LIKE CONCAT('%', #{keyword}, '%')
         OR production_line LIKE CONCAT('%', #{keyword}, '%')
         OR workstation LIKE CONCAT('%', #{keyword}, '%'))


    AND andon_config_id = #{andonConfigId}


    AND status = #{status}


    AND production_line = #{productionLine}


    AND init_time >= #{startTime}


    AND init_time <= #{endTime}

ORDER BY id DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*)
FROM andon_record
WHERE is_deleted = 0

    AND (description LIKE CONCAT('%', #{keyword}, '%')
         OR production_line LIKE CONCAT('%', #{keyword}, '%')
         OR workstation LIKE CONCAT('%', #{keyword}, '%'))


    AND andon_config_id = #{andonConfigId}


    AND status = #{status}


    AND production_line = #{productionLine}


    AND init_time >= #{startTime}


    AND init_time <= #{endTime}
